tool_schemas.implementation:
def sequentialthinking(action, run_id=None, step_id=None, tool_call_id=None, agent_id=None, body=None, filters=None, sort=None, page=None, page_size=None, **_extra):
    import json, os, datetime, time, re, random

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0228000" if __import__("os").path.isdir("./environment_mix/0228000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    RUN_RE = re.compile(r"^mas_run_[0-9A-HJKMNP-TV-Z]{10,}$")
    STP_RE = re.compile(r"^mas_stp_[0-9A-HJKMNP-TV-Z]{10,}$")
    TCL_RE = re.compile(r"^mas_tcl_[0-9A-HJKMNP-TV-Z]{10,}$")
    AGT_RE = re.compile(r"^mas_agt_[0-9A-HJKMNP-TV-Z]{10,}$")

    RUN_STAT = {"queued", "running", "completed", "failed", "cancelled"}
    RUN_TRANS = {
        "queued": {"running", "cancelled"},
        "running": {"completed", "failed", "cancelled"},
        "completed": set(),
        "failed": set(),
        "cancelled": set(),
    }
    STEP_STAT = {"queued", "running", "completed", "failed", "skipped", "cancelled"}
    STEP_TRANS = {
        "queued": {"running", "skipped", "cancelled"},
        "running": {"completed", "failed", "cancelled"},
        "completed": set(),
        "failed": set(),
        "skipped": set(),
        "cancelled": set(),
    }
    TCL_STAT = {"queued", "running", "succeeded", "failed", "cancelled"}
    TCL_TRANS = {
        "queued": {"running", "cancelled"},
        "running": {"succeeded", "failed", "cancelled"},
        "succeeded": set(),
        "failed": set(),
        "cancelled": set(),
    }
    AGT_ROLE = {"planner", "executor", "researcher", "critic", "summarizer", "router", "tooling"}

    def _parse_dt(s):
        if s is None:
            return None
        if not isinstance(s, str) or not s:
            return None
        try:
            if s.endswith("Z"):
                s2 = s[:-1] + "+00:00"
            else:
                s2 = s
            datetime.datetime.fromisoformat(s2)
            return s
        except Exception:
            return None

    def _gen_ulid_like(prefix):
        alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
        return prefix + "".join(random.choice(alphabet) for _ in range(16))

    def _find_by_id(rows, _id):
        for r in rows:
            if r.get("id") == _id:
                return r
        return None

    def _require_id(name, value, regex):
        if value is None:
            return _err("VALIDATION_ERROR", f"Missing required identifier: {name}")
        if not isinstance(value, str) or not regex.match(value):
            return _err("VALIDATION_ERROR", f"Invalid {name} format")
        return None

    def _validate_page(ps, p):
        if p is None:
            p = 1
        if ps is None:
            ps = 50
        if not isinstance(p, int) or p < 1:
            return None, None, _err("VALIDATION_ERROR", "page must be an integer >= 1")
        if not isinstance(ps, int) or ps < 1 or ps > 200:
            return None, None, _err("VALIDATION_ERROR", "page_size must be an integer between 1 and 200")
        return ps, p, None

    def _apply_filters(rows, f):
        if not f:
            return rows
        if not isinstance(f, dict):
            return None
        out = rows
        for k, v in f.items():
            if k == "status":
                out = [r for r in out if r.get("status") == v]
            elif k == "run_id":
                out = [r for r in out if r.get("run_id") == v]
            elif k == "step_id":
                out = [r for r in out if r.get("step_id") == v]
            elif k == "agent_id":
                out = [r for r in out if r.get("agent_id") == v]
            elif k == "enabled":
                out = [r for r in out if r.get("enabled") is v]
            else:
                return None
        return out

    def _sort_rows(rows, sort_obj):
        if not sort_obj:
            return rows
        if not isinstance(sort_obj, dict):
            return None
        field = sort_obj.get("field")
        direction = sort_obj.get("direction")
        allowed = {"created_at", "updated_at", "started_at", "completed_at", "step_index", "sequence_index"}
        if field not in allowed or direction not in {"asc", "desc"}:
            return None
        rev = direction == "desc"
        def keyfn(r):
            val = r.get(field)
            if val is None:
                return (1, "")
            return (0, val)
        return sorted(rows, key=keyfn, reverse=rev)

    def _paginate(rows, ps, p):
        total = len(rows)
        start = (p - 1) * ps
        end = start + ps
        items = rows[start:end]
        has_more = end < total
        next_cursor = (p + 1) if has_more else None
        return items, {"total": total, "page": p, "page_size": ps, "has_more": has_more, "next_cursor": next_cursor}

    def _len_ok(s, maxlen):
        return s is None or (isinstance(s, str) and len(s) <= maxlen)

    # Load collections
    runs = _load("runs.json")
    steps = _load("steps.json")
    tool_calls = _load("tool_calls.json")
    agents = _load("agents.json")
    api_requests = _load("api_requests.json")

    # Create api_requests row for every invocation
    req_id = _gen_ulid_like("mas_req_")
    request_body = {} if body is None and filters is None and sort is None and page is None and page_size is None and run_id is None and step_id is None and tool_call_id is None and agent_id is None else {
        "action": action,
        "run_id": run_id,
        "step_id": step_id,
        "tool_call_id": tool_call_id,
        "agent_id": agent_id,
        "body": body if body is not None else None,
        "filters": filters if filters is not None else None,
        "sort": sort if sort is not None else None,
        "page": page if page is not None else None,
        "page_size": page_size if page_size is not None else None,
    }

    api_req_row = {
        "id": req_id,
        "tool": "sequentialthinking",
        "run_id": None,
        "idempotency_key": None,
        "caller": {},
        "request_headers": {},
        "request_body": request_body if isinstance(request_body, dict) else {},
        "response_body": None,
        "http_status": None,
        "duration_ms": None,
        "created_at": now,
        "updated_at": now,
    }
    api_requests.append(api_req_row)
    _save("api_requests.json", api_requests)

    def _finalize(resp, http_status):
        duration_ms = int((time.time() - t0) * 1000)
        api_req_row["response_body"] = resp
        api_req_row["http_status"] = http_status
        api_req_row["duration_ms"] = duration_ms if duration_ms >= 0 else 0
        api_req_row["updated_at"] = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
        _save("api_requests.json", api_requests)
        return resp

    # Validate action
    allowed_actions = {
        "create_run","get_run","list_runs","update_run","cancel_run",
        "create_step","get_step","list_steps","update_step",
        "create_tool_call","get_tool_call","list_tool_calls","update_tool_call",
        "create_agent","get_agent","list_agents","update_agent"
    }
    if action not in allowed_actions:
        return _finalize(_err("VALIDATION_ERROR", "Invalid action"), 400)

    # Helpers for run completion constraints
    def _run_steps(runid):
        return [s for s in steps if s.get("run_id") == runid]

    def _check_run_can_complete(run_row):
        rs = _run_steps(run_row["id"])
        for st in rs:
            if st.get("status") != "skipped" and st.get("status") != "completed":
                return False
        # contiguous step_index starting at 0 with no gaps if completed
        idxs = sorted([st.get("step_index") for st in rs if isinstance(st.get("step_index"), int) and st.get("step_index") >= 0])
        if not idxs:
            return True
        if idxs[0] != 0:
            return False
        for i in range(len(idxs)):
            if idxs[i] != i:
                return False
        return True

    # Actions
    if action == "create_run":
        if body is None or not isinstance(body, dict) or "run" not in body or not isinstance(body.get("run"), dict):
            return _finalize(_err("VALIDATION_ERROR", "Missing body.run for create_run"), 400)
        run_body = body["run"]
        # Validate lengths/types
        if "status" in run_body and run_body["status"] not in RUN_STAT:
            return _finalize(_err("VALIDATION_ERROR", "Invalid run.status"), 400)
        if "input_prompt" in run_body and not _len_ok(run_body.get("input_prompt"), 200000):
            return _finalize(_err("VALIDATION_ERROR", "input_prompt too long"), 400)
        if "final_output" in run_body and not _len_ok(run_body.get("final_output"), 200000):
            return _finalize(_err("VALIDATION_ERROR", "final_output too long"), 400)
        for dtf in ("started_at", "completed_at"):
            if dtf in run_body and run_body[dtf] is not None and _parse_dt(run_body[dtf]) is None:
                return _finalize(_err("VALIDATION_ERROR", f"Invalid {dtf} date-time"), 400)
        if "metadata" in run_body and not isinstance(run_body["metadata"], dict):
            return _finalize(_err("VALIDATION_ERROR", "metadata must be an object"), 400)

        rid = _gen_ulid_like("mas_run_")
        status = run_body.get("status", "queued")
        started_at = run_body.get("started_at")
        completed_at = run_body.get("completed_at")

        # Enforce status/time constraints
        if status == "running" and started_at is None:
            started_at = now
        if status in {"completed", "failed", "cancelled"} and completed_at is None:
            completed_at = now
        if completed_at is not None and started_at is None:
            return _finalize(_err("VALIDATION_ERROR", "completed_at requires started_at"), 400)

        new_run = {
            "id": rid,
            "status": status,
            "input_prompt": run_body.get("input_prompt"),
            "final_output": run_body.get("final_output"),
            "error_code": run_body.get("error_code"),
            "error_message": run_body.get("error_message"),
            "started_at": started_at,
            "completed_at": completed_at,
            "metadata": run_body.get("metadata", {}),
            "created_at": now,
            "updated_at": now,
        }
        runs.append(new_run)
        _save("runs.json", runs)
        api_req_row["run_id"] = rid
        return _finalize({"run": new_run}, 200)

    if action == "get_run":
        e = _require_id("run_id", run_id, RUN_RE)
        if e: return _finalize(e, 400)
        r = _find_by_id(runs, run_id)
        if not r:
            return _finalize(_err("NOT_FOUND", "Run not found"), 404)
        api_req_row["run_id"] = r["id"]
        return _finalize({"run": r}, 200)

    if action == "list_runs":
        ps, p, e = _validate_page(page_size, page)
        if e: return _finalize(e, 400)
        rows = runs[:]
        rows2 = _apply_filters(rows, filters)
        if rows2 is None:
            return _finalize(_err("VALIDATION_ERROR", "Invalid filters"), 400)
        rows3 = _sort_rows(rows2, sort)
        if rows3 is None:
            return _finalize(_err("VALIDATION_ERROR", "Invalid sort"), 400)
        items, meta = _paginate(rows3, ps, p)
        return _finalize({"runs": items, "page": meta}, 200)

    if action == "update_run":
        e = _require_id("run_id", run_id, RUN_RE)
        if e: return _finalize(e, 400)
        if body is None or not isinstance(body, dict) or "run" not in body or not isinstance(body.get("run"), dict):
            return _finalize(_err("VALIDATION_ERROR", "Missing body.run for update_run"), 400)
        run_row = _find_by_id(runs, run_id)
        if not run_row:
            return _finalize(_err("NOT_FOUND", "Run not found"), 404)

        patch = body["run"]
        if "status" in patch and patch["status"] not in RUN_STAT:
            return _finalize(_err("VALIDATION_ERROR", "Invalid run.status"), 400)
        if "input_prompt" in patch and not _len_ok(patch.get("input_prompt"), 200000):
            return _finalize(_err("VALIDATION_ERROR", "input_prompt too long"), 400)
        if "final_output" in patch and not _len_ok(patch.get("final_output"), 200000):
            return _finalize(_err("VALIDATION_ERROR", "final_output too long"), 400)
        for dtf in ("started_at", "completed_at"):
            if dtf in patch and patch[dtf] is not None and _parse_dt(patch[dtf]) is None:
                return _finalize(_err("VALIDATION_ERROR", f"Invalid {dtf} date-time"), 400)
        if "metadata" in patch and not isinstance(patch["metadata"], dict):
            return _finalize(_err("VALIDATION_ERROR", "metadata must be an object"), 400)

        old_status = run_row.get("status")
        new_status = patch.get("status", old_status)

        if new_status != old_status:
            if new_status not in RUN_TRANS.get(old_status, set()):
                return _finalize(_err("INVALID_TRANSITION", f"Run cannot transition from {old_status} to {new_status}"), 409)
            # if completing, enforce all non-skipped steps completed + contiguous indices
            if new_status == "completed":
                if not _check_run_can_complete(run_row):
                    return _finalize(_err("INVALID_TRANSITION", "Run cannot complete until all non-skipped steps are completed and step_index is contiguous from 0"), 409)

        # Apply patch
        for k in ("input_prompt","final_output","error_code","error_message","metadata"):
            if k in patch:
                run_row[k] = patch[k]
        if "started_at" in patch:
            run_row["started_at"] = patch["started_at"]
        if "completed_at" in patch:
            run_row["completed_at"] = patch["completed_at"]
        if "status" in patch:
            run_row["status"] = new_status

        # Enforce status/time constraints after patch
        if run_row["status"] == "running" and run_row.get("started_at") is None:
            run_row["started_at"] = now
        if run_row["status"] in {"completed", "failed", "cancelled"} and run_row.get("completed_at") is None:
            run_row["completed_at"] = now
        if run_row.get("completed_at") is not None and run_row.get("started_at") is None:
            return _finalize(_err("VALIDATION_ERROR", "completed_at requires started_at"), 400)

        run_row["updated_at"] = now
        _save("runs.json", runs)
        api_req_row["run_id"] = run_row["id"]
        return _finalize({"run": run_row}, 200)

    if action == "cancel_run":
        e = _require_id("run_id", run_id, RUN_RE)
        if e: return _finalize(e, 400)
        run_row = _find_by_id(runs, run_id)
        if not run_row:
            return _finalize(_err("NOT_FOUND", "Run not found"), 404)
        old_status = run_row["status"]
        if old_status == "cancelled":
            api_req_row["run_id"] = run_row["id"]
            return _finalize({"run": run_row}, 200)
        if "cancelled" not in RUN_TRANS.get(old_status, set()):
            return _finalize(_err("INVALID_TRANSITION", f"Run cannot transition from {old_status} to cancelled"), 409)
        run_row["status"] = "cancelled"
        if run_row.get("started_at") is None and old_status == "queued":
            run_row["started_at"] = now
        run_row["completed_at"] = now
        run_row["updated_at"] = now
        _save("runs.json", runs)
        api_req_row["run_id"] = run_row["id"]
        return _finalize({"run": run_row}, 200)

    if action == "create_step":
        if body is None or not isinstance(body, dict) or "step" not in body or not isinstance(body.get("step"), dict):
            return _finalize(_err("VALIDATION_ERROR", "Missing body.step for create_step"), 400)
        st_body = body["step"]

        # required: run_id, step_index
        rid = st_body.get("run_id")
        if rid is None or not isinstance(rid, str) or not RUN_RE.match(rid):
            return _finalize(_err("VALIDATION_ERROR", "Invalid step.run_id"), 400)
        if "step_index" not in st_body or not isinstance(st_body.get("step_index"), int) or st_body["step_index"] < 0:
            return _finalize(_err("VALIDATION_ERROR", "Invalid step.step_index"), 400)

        run_row = _find_by_id(runs, rid)
        if not run_row:
            return _finalize(_err("NOT_FOUND", "Parent run not found"), 404)

        if "status" in st_body and st_body["status"] not in STEP_STAT:
            return _finalize(_err("VALIDATION_ERROR", "Invalid step.status"), 400)
        if "agent_id" in st_body and st_body["agent_id"] is not None:
            if not isinstance(st_body["agent_id"], str) or not AGT_RE.match(st_body["agent_id"]):
                return _finalize(_err("VALIDATION_ERROR", "Invalid step.agent_id"), 400)
            ag = _find_by_id(agents, st_body["agent_id"])
            if not ag:
                return _finalize(_err("NOT_FOUND", "Agent not found"), 404)
            if ag.get("enabled") is not True:
                return _finalize(_err("CONFLICT", "Agent is disabled and cannot be newly assigned"), 409)

        if "thought" in st_body and not _len_ok(st_body.get("thought"), 200000):
            return _finalize(_err("VALIDATION_ERROR", "thought too long"), 400)
        if "result" in st_body and not _len_ok(st_body.get("result"), 200000):
            return _finalize(_err("VALIDATION_ERROR", "result too long"), 400)
        for dtf in ("started_at","completed_at"):
            if dtf in st_body and st_body[dtf] is not None and _parse_dt(st_body[dtf]) is None:
                return _finalize(_err("VALIDATION_ERROR", f"Invalid {dtf} date-time"), 400)

        # unique(run_id, step_index)
        for s in steps:
            if s.get("run_id") == rid and s.get("step_index") == st_body["step_index"]:
                return _finalize(_err("CONFLICT", "Step with this (run_id, step_index) already exists"), 409)

        sid = _gen_ulid_like("mas_stp_")
        status = st_body.get("status", "queued")
        started_at = st_body.get("started_at")
        completed_at = st_body.get("completed_at")

        # transitions constraints relative to run
        if status == "running" and run_row.get("status") != "running":
            return _finalize(_err("INVALID_TRANSITION", "Step cannot transition to running unless parent run is running"), 409)

        if status == "running" and started_at is None:
            started_at = now
        if status in {"completed", "failed", "cancelled"} and completed_at is None:
            completed_at = now

        new_step = {
            "id": sid,
            "run_id": rid,
            "step_index": st_body["step_index"],
            "status": status,
            "agent_id": st_body.get("agent_id"),
            "instruction": st_body.get("instruction"),
            "thought": st_body.get("thought"),
            "result": st_body.get("result"),
            "error_message": st_body.get("error_message"),
            "started_at": started_at,
            "completed_at": completed_at,
            "created_at": now,
            "updated_at": now,
        }
        steps.append(new_step)
        _save("steps.json", steps)
        api_req_row["run_id"] = rid
        return _finalize({"step": new_step}, 200)

    if action == "get_step":
        e = _require_id("step_id", step_id, STP_RE)
        if e: return _finalize(e, 400)
        st = _find_by_id(steps, step_id)
        if not st:
            return _finalize(_err("NOT_FOUND", "Step not found"), 404)
        api_req_row["run_id"] = st.get("run_id")
        return _finalize({"step": st}, 200)

    if action == "list_steps":
        ps, p, e = _validate_page(page_size, page)
        if e: return _finalize(e, 400)
        rows = steps[:]
        rows2 = _apply_filters(rows, filters)
        if rows2 is None:
            return _finalize(_err("VALIDATION_ERROR", "Invalid filters"), 400)
        rows3 = _sort_rows(rows2, sort)
        if rows3 is None:
            return _finalize(_err("VALIDATION_ERROR", "Invalid sort"), 400)
        items, meta = _paginate(rows3, ps, p)
        return _finalize({"steps": items, "page": meta}, 200)

    if action == "update_step":
        e = _require_id("step_id", step_id, STP_RE)
        if e: return _finalize(e, 400)
        if body is None or not isinstance(body, dict) or "step" not in body or not isinstance(body.get("step"), dict):
            return _finalize(_err("VALIDATION_ERROR", "Missing body.step for update_step"), 400)

        st = _find_by_id(steps, step_id)
        if not st:
            return _finalize(_err("NOT_FOUND", "Step not found"), 404)
        run_row = _find_by_id(runs, st.get("run_id"))
        if not run_row:
            return _finalize(_err("NOT_FOUND", "Parent run not found"), 404)

        patch = body["step"]
        if "status" in patch and patch["status"] not in STEP_STAT:
            return _finalize(_err("VALIDATION_ERROR", "Invalid step.status"), 400)
        if "step_index" in patch:
            if not isinstance(patch["step_index"], int) or patch["step_index"] < 0:
                return _finalize(_err("VALIDATION_ERROR", "Invalid step.step_index"), 400)
            # unique(run_id, step_index)
            for s2 in steps:
                if s2.get("id") != st["id"] and s2.get("run_id") == st.get("run_id") and s2.get("step_index") == patch["step_index"]:
                    return _finalize(_err("CONFLICT", "Step with this (run_id, step_index) already exists"), 409)
        if "agent_id" in patch and patch["agent_id"] is not None:
            if not isinstance(patch["agent_id"], str) or not AGT_RE.match(patch["agent_id"]):
                return _finalize(_err("VALIDATION_ERROR", "Invalid step.agent_id"), 400)
            if patch["agent_id"] != st.get("agent_id"):
                ag = _find_by_id(agents, patch["agent_id"])
                if not ag:
                    return _finalize(_err("NOT_FOUND", "Agent not found"), 404)
                if ag.get("enabled") is not True:
                    return _finalize(_err("CONFLICT", "Agent is disabled and cannot be newly assigned"), 409)

        if "thought" in patch and not _len_ok(patch.get("thought"), 200000):
            return _finalize(_err("VALIDATION_ERROR", "thought too long"), 400)
        if "result" in patch and not _len_ok(patch.get("result"), 200000):
            return _finalize(_err("VALIDATION_ERROR", "result too long"), 400)
        for dtf in ("started_at","completed_at"):
            if dtf in patch and patch[dtf] is not None and _parse_dt(patch[dtf]) is None:
                return _finalize(_err("VALIDATION_ERROR", f"Invalid {dtf} date-time"), 400)

        old_status = st.get("status")
        new_status = patch.get("status", old_status)
        if new_status != old_status:
            if new_status not in STEP_TRANS.get(old_status, set()):
                return _finalize(_err("INVALID_TRANSITION", f"Step cannot transition from {old_status} to {new_status}"), 409)
            if new_status == "running" and run_row.get("status") != "running":
                return _finalize(_err("INVALID_TRANSITION", "Step cannot transition to running unless parent run is running"), 409)

        # Apply patch
        for k in ("run_id","step_index","agent_id","instruction","thought","result","error_message"):
            if k in patch:
                if k == "run_id":
                    # disallow changing run_id to preserve integrity for this API
                    if patch["run_id"] != st.get("run_id"):
                        return _finalize(_err("VALIDATION_ERROR", "Changing step.run_id is not supported"), 400)
                else:
                    st[k] = patch[k]
        if "started_at" in patch:
            st["started_at"] = patch["started_at"]
        if "completed_at" in patch:
            st["completed_at"] = patch["completed_at"]
        if "status" in patch:
            st["status"] = new_status

        # auto timestamps
        if st["status"] == "running" and st.get("started_at") is None:
            st["started_at"] = now
        if st["status"] in {"completed","failed","cancelled"} and st.get("completed_at") is None:
            st["completed_at"] = now

        st["updated_at"] = now
        _save("steps.json", steps)
        api_req_row["run_id"] = st.get("run_id")
        return _finalize({"step": st}, 200)

    if action == "create_tool_call":
        if body is None or not isinstance(body, dict) or "tool_call" not in body or not isinstance(body.get("tool_call"), dict):
            return _finalize(_err("VALIDATION_ERROR", "Missing body.tool_call for create_tool_call"), 400)
        tc_body = body["tool_call"]

        rid = tc_body.get("run_id")
        sid = tc_body.get("step_id")
        if rid is None or not isinstance(rid, str) or not RUN_RE.match(rid):
            return _finalize(_err("VALIDATION_ERROR", "Invalid tool_call.run_id"), 400)
        if sid is None or not isinstance(sid, str) or not STP_RE.match(sid):
            return _finalize(_err("VALIDATION_ERROR", "Invalid tool_call.step_id"), 400)
        if "sequence_index" not in tc_body or not isinstance(tc_body.get("sequence_index"), int) or tc_body["sequence_index"] < 0:
            return _finalize(_err("VALIDATION_ERROR", "Invalid tool_call.sequence_index"), 400)
        if "tool_name" not in tc_body or not isinstance(tc_body.get("tool_name"), str) or not tc_body["tool_name"]:
            return _finalize(_err("VALIDATION_ERROR", "tool_call.tool_name is required"), 400)
        if "input" not in tc_body or not isinstance(tc_body.get("input"), dict):
            return _finalize(_err("VALIDATION_ERROR", "tool_call.input must be an object"), 400)
        if "output" in tc_body and tc_body["output"] is not None and not isinstance(tc_body["output"], dict):
            return _finalize(_err("VALIDATION_ERROR", "tool_call.output must be an object when present"), 400)
        if "status" in tc_body and tc_body["status"] not in TCL_STAT:
            return _finalize(_err("VALIDATION_ERROR", "Invalid tool_call.status"), 400)
        if "duration_ms" in tc_body and tc_body["duration_ms"] is not None:
            if not isinstance(tc_body["duration_ms"], int) or tc_body["duration_ms"] < 0:
                return _finalize(_err("VALIDATION_ERROR", "duration_ms must be a non-negative integer"), 400)

        run_row = _find_by_id(runs, rid)
        if not run_row:
            return _finalize(_err("NOT_FOUND", "Parent run not found"), 404)
        step_row = _find_by_id(steps, sid)
        if not step_row or step_row.get("run_id") != rid:
            return _finalize(_err("NOT_FOUND", "Parent step not found for this run"), 404)

        # unique(step_id, sequence_index)
        for tc in tool_calls:
            if tc.get("step_id") == sid and tc.get("sequence_index") == tc_body["sequence_index"]:
                return _finalize(_err("CONFLICT", "Tool call with this (step_id, sequence_index) already exists"), 409)

        tcid = _gen_ulid_like("mas_tcl_")
        status = tc_body.get("status", "queued")
        new_tc = {
            "id": tcid,
            "run_id": rid,
            "step_id": sid,
            "sequence_index": tc_body["sequence_index"],
            "tool_name": tc_body["tool_name"],
            "status": status,
            "input": tc_body["input"],
            "output": tc_body.get("output"),
            "error_message": tc_body.get("error_message"),
            "duration_ms": tc_body.get("duration_ms"),
            "created_at": now,
            "updated_at": now,
        }
        tool_calls.append(new_tc)
        _save("tool_calls.json", tool_calls)
        api_req_row["run_id"] = rid
        return _finalize({"tool_call": new_tc}, 200)

    if action == "get_tool_call":
        e = _require_id("tool_call_id", tool_call_id, TCL_RE)
        if e: return _finalize(e, 400)
        tc = _find_by_id(tool_calls, tool_call_id)
        if not tc:
            return _finalize(_err("NOT_FOUND", "Tool call not found"), 404)
        api_req_row["run_id"] = tc.get("run_id")
        return _finalize({"tool_call": tc}, 200)

    if action == "list_tool_calls":
        ps, p, e = _validate_page(page_size, page)
        if e: return _finalize(e, 400)
        rows = tool_calls[:]
        rows2 = _apply_filters(rows, filters)
        if rows2 is None:
            return _finalize(_err("VALIDATION_ERROR", "Invalid filters"), 400)
        rows3 = _sort_rows(rows2, sort)
        if rows3 is None:
            return _finalize(_err("VALIDATION_ERROR", "Invalid sort"), 400)
        items, meta = _paginate(rows3, ps, p)
        return _finalize({"tool_calls": items, "page": meta}, 200)

    if action == "update_tool_call":
        e = _require_id("tool_call_id", tool_call_id, TCL_RE)
        if e: return _finalize(e, 400)
        if body is None or not isinstance(body, dict) or "tool_call" not in body or not isinstance(body.get("tool_call"), dict):
            return _finalize(_err("VALIDATION_ERROR", "Missing body.tool_call for update_tool_call"), 400)

        tc = _find_by_id(tool_calls, tool_call_id)
        if not tc:
            return _finalize(_err("NOT_FOUND", "Tool call not found"), 404)

        patch = body["tool_call"]
        if "sequence_index" in patch:
            if not isinstance(patch["sequence_index"], int) or patch["sequence_index"] < 0:
                return _finalize(_err("VALIDATION_ERROR", "Invalid tool_call.sequence_index"), 400)
            for tc2 in tool_calls:
                if tc2.get("id") != tc["id"] and tc2.get("step_id") == tc.get("step_id") and tc2.get("sequence_index") == patch["sequence_index"]:
                    return _finalize(_err("CONFLICT", "Tool call with this (step_id, sequence_index) already exists"), 409)
        if "tool_name" in patch and (not isinstance(patch["tool_name"], str) or not patch["tool_name"]):
            return _finalize(_err("VALIDATION_ERROR", "tool_call.tool_name cannot be empty"), 400)
        if "input" in patch and (patch["input"] is None or not isinstance(patch["input"], dict)):
            return _finalize(_err("VALIDATION_ERROR", "tool_call.input must be an object"), 400)
        if "output" in patch and patch["output"] is not None and not isinstance(patch["output"], dict):
            return _finalize(_err("VALIDATION_ERROR", "tool_call.output must be an object when present"), 400)
        if "duration_ms" in patch and patch["duration_ms"] is not None:
            if not isinstance(patch["duration_ms"], int) or patch["duration_ms"] < 0:
                return _finalize(_err("VALIDATION_ERROR", "duration_ms must be a non-negative integer"), 400)
        if "status" in patch and patch["status"] not in TCL_STAT:
            return _finalize(_err("VALIDATION_ERROR", "Invalid tool_call.status"), 400)

        old_status = tc.get("status")
        new_status = patch.get("status", old_status)
        if new_status != old_status:
            if new_status not in TCL_TRANS.get(old_status, set()):
                return _finalize(_err("INVALID_TRANSITION", f"Tool call cannot transition from {old_status} to {new_status}"), 409)

        for k in ("sequence_index","tool_name","input","output","error_message","duration_ms"):
            if k in patch:
                tc[k] = patch[k]
        if "status" in patch:
            tc["status"] = new_status

        tc["updated_at"] = now
        _save("tool_calls.json", tool_calls)
        api_req_row["run_id"] = tc.get("run_id")
        return _finalize({"tool_call": tc}, 200)

    if action == "create_agent":
        if body is None or not isinstance(body, dict) or "agent" not in body or not isinstance(body.get("agent"), dict):
            return _finalize(_err("VALIDATION_ERROR", "Missing body.agent for create_agent"), 400)
        ag_body = body["agent"]
        if "name" not in ag_body or not isinstance(ag_body.get("name"), str) or not ag_body["name"]:
            return _finalize(_err("VALIDATION_ERROR", "agent.name is required and cannot be empty"), 400)
        if "role" not in ag_body or ag_body.get("role") not in AGT_ROLE:
            return _finalize(_err("VALIDATION_ERROR", "Invalid agent.role"), 400)
        if "enabled" not in ag_body or not isinstance(ag_body.get("enabled"), bool):
            return _finalize(_err("VALIDATION_ERROR", "agent.enabled must be boolean"), 400)
        if "config" not in ag_body or not isinstance(ag_body.get("config"), dict):
            return _finalize(_err("VALIDATION_ERROR", "agent.config must be an object"), 400)
        # unique(name)
        for a in agents:
            if a.get("name") == ag_body["name"]:
                return _finalize(_err("CONFLICT", "Agent name must be unique"), 409)

        aid = _gen_ulid_like("mas_agt_")
        new_ag = {
            "id": aid,
            "name": ag_body["name"],
            "role": ag_body["role"],
            "enabled": ag_body["enabled"],
            "config": ag_body["config"],
            "created_at": now,
            "updated_at": now,
        }
        agents.append(new_ag)
        _save("agents.json", agents)
        return _finalize({"agent": new_ag}, 200)

    if action == "get_agent":
        e = _require_id("agent_id", agent_id, AGT_RE)
        if e: return _finalize(e, 400)
        ag = _find_by_id(agents, agent_id)
        if not ag:
            return _finalize(_err("NOT_FOUND", "Agent not found"), 404)
        return _finalize({"agent": ag}, 200)

    if action == "list_agents":
        ps, p, e = _validate_page(page_size, page)
        if e: return _finalize(e, 400)
        rows = agents[:]
        rows2 = _apply_filters(rows, filters)
        if rows2 is None:
            return _finalize(_err("VALIDATION_ERROR", "Invalid filters"), 400)
        # allow sorting by created_at/updated_at only here; reuse sorter but it supports those
        rows3 = _sort_rows(rows2, sort)
        if rows3 is None:
            return _finalize(_err("VALIDATION_ERROR", "Invalid sort"), 400)
        items, meta = _paginate(rows3, ps, p)
        return _finalize({"agents": items, "page": meta}, 200)

    if action == "update_agent":
        e = _require_id("agent_id", agent_id, AGT_RE)
        if e: return _finalize(e, 400)
        if body is None or not isinstance(body, dict) or "agent" not in body or not isinstance(body.get("agent"), dict):
            return _finalize(_err("VALIDATION_ERROR", "Missing body.agent for update_agent"), 400)
        ag = _find_by_id(agents, agent_id)
        if not ag:
            return _finalize(_err("NOT_FOUND", "Agent not found"), 404)

        patch = body["agent"]
        if "name" in patch:
            if not isinstance(patch["name"], str) or not patch["name"]:
                return _finalize(_err("VALIDATION_ERROR", "agent.name cannot be empty"), 400)
            if patch["name"] != ag.get("name"):
                for a2 in agents:
                    if a2.get("id") != ag["id"] and a2.get("name") == patch["name"]:
                        return _finalize(_err("CONFLICT", "Agent name must be unique"), 409)
        if "role" in patch and patch["role"] not in AGT_ROLE:
            return _finalize(_err("VALIDATION_ERROR", "Invalid agent.role"), 400)
        if "enabled" in patch and not isinstance(patch["enabled"], bool):
            return _finalize(_err("VALIDATION_ERROR", "agent.enabled must be boolean"), 400)
        if "config" in patch and (patch["config"] is None or not isinstance(patch["config"], dict)):
            return _finalize(_err("VALIDATION_ERROR", "agent.config must be an object"), 400)

        # enabled lifecycle transition always allowed toggle; enforce boolean
        for k in ("name","role","enabled","config"):
            if k in patch:
                ag[k] = patch[k]
        ag["updated_at"] = now
        _save("agents.json", agents)
        return _finalize({"agent": ag}, 200)

    return _finalize(_err("VALIDATION_ERROR", "Unhandled action"), 400)

def sequentialthinking_auth(authorization, include_rate_limits=None, **_extra):
    import json, os, datetime, time, random, re

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0228000" if __import__("os").path.isdir("./environment_mix/0228000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now_dt = datetime.datetime.utcnow().replace(microsecond=0)
    now = now_dt.isoformat() + "Z"

    if include_rate_limits is None:
        include_rate_limits = True

    # Validate inputs
    if not isinstance(authorization, str) or not authorization.strip():
        return _err("VALIDATION_ERROR", "authorization must be a non-empty string")
    if not isinstance(include_rate_limits, bool):
        return _err("VALIDATION_ERROR", "include_rate_limits must be a boolean")

    m = re.match(r"^\s*Bearer\s+(.+?)\s*$", authorization)
    if not m:
        return _err("VALIDATION_ERROR", "authorization must be of the form 'Bearer <token>'")
    token = m.group(1)

    _CROCK = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
    def _gen(prefix):
        ts = int(time.time() * 1000)
        out = []
        for _ in range(10):
            out.append(_CROCK[ts % 32])
            ts //= 32
        for _ in range(16):
            out.append(_CROCK[random.randint(0, 31)])
        return prefix + "".join(out)

    # Load requests log early (observable dynamics)
    api_requests = _load("api_requests.json")

    # Best-effort "credential" resolution:
    # This datastore schema does not include a credentials table. A real service would validate the token.
    # Here, we treat any non-empty bearer token as an authenticated principal for introspection, and we
    # record the request for auditability.
    audit_row = {
        "id": _gen("mas_req_"),
        "tool": "sequentialthinking",
        "run_id": None,
        "idempotency_key": None,
        "caller": {"principal": "bearer_token", "token_fingerprint": token[:12]},
        "request_headers": {"authorization_present": True},
        "request_body": {},  # tool request body is typically {}
        "response_body": None,
        "http_status": None,
        "duration_ms": None,
        "created_at": now,
        "updated_at": now,
    }
    api_requests.append(audit_row)
    _save("api_requests.json", api_requests)

    def _finalize(resp, status):
        dur = int((time.time() - t0) * 1000)
        if dur < 0:
            dur = 0
        audit_row["response_body"] = resp
        audit_row["http_status"] = int(status)
        audit_row["duration_ms"] = dur
        audit_row["updated_at"] = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
        _save("api_requests.json", api_requests)
        return resp

    # Rate-limit/quota: not declared in schema; provide consumption derived from api_requests volume.
    # Refuse only if an explicit, enforceable limit exists (none here).
    if include_rate_limits:
        window_s = 60
        cutoff = (now_dt - datetime.timedelta(seconds=window_s))
        def _parse_dt(s):
            try:
                if isinstance(s, str) and s.endswith("Z"):
                    s = s[:-1]
                return datetime.datetime.fromisoformat(s)
            except Exception:
                return None

        recent = 0
        total = 0
        for r in api_requests:
            if r.get("tool") != "sequentialthinking":
                continue
            total += 1
            dt = _parse_dt(r.get("created_at"))
            if dt and dt >= cutoff:
                recent += 1

        rate_limits = {
            "requests_last_60s": recent,
            "requests_total": total,
            "enforced": False
        }
    else:
        rate_limits = None

    resp = {
        "authenticated": True,
        "identity": {
            "type": "bearer_token",
            "token_fingerprint": token[:12],
        },
        "scopes": ["audit:read", "runs:read"],
        "rate_limits": rate_limits
    }
    return _finalize(resp, 200)

def sequentialthinking_api_requests(action, api_request_id=None, page=None, page_size=None, sort=None, filters=None, **_extra):
    import json, os, datetime, time, re, random

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0228000" if __import__("os").path.isdir("./environment_mix/0228000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()

    # ---- helpers ----
    CROCK = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"

    def _now_iso():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _parse_dt(s):
        if s is None:
            return None
        if isinstance(s, datetime.datetime):
            return s
        if not isinstance(s, str) or not s.strip():
            return None
        ss = s.strip()
        try:
            if ss.endswith("Z"):
                return datetime.datetime.fromisoformat(ss[:-1])
            return datetime.datetime.fromisoformat(ss)
        except ValueError:
            return None

    def _ulid_like(prefix):
        # 26 chars Crockford base32: 10 time + 16 random
        ms = int(time.time() * 1000)
        tchars = []
        tmp = ms
        for _ in range(10):
            tchars.append(CROCK[tmp % 32])
            tmp //= 32
        tchars = list(reversed(tchars))
        rchars = [CROCK[random.randint(0, 31)] for _ in range(16)]
        return prefix + "".join(tchars + rchars)

    def _ensure_api_requests_list(db_obj):
        # file might store either list or {"rows":[...]}
        if isinstance(db_obj, list):
            return db_obj, "list"
        if isinstance(db_obj, dict):
            rows = db_obj.get("rows")
            if isinstance(rows, list):
                return rows, "dict_rows"
        return [], "list"

    def _save_api_requests(original, mode, rows):
        if mode == "dict_rows" and isinstance(original, dict):
            original["rows"] = rows
            _save("api_requests.json", original)
        else:
            _save("api_requests.json", rows)

    def _coerce_int(v, name):
        if v is None:
            return None
        if isinstance(v, bool):
            return None
        if isinstance(v, int):
            return v
        return None

    def _get_sort_key(row, key):
        # only top-level keys supported; unknown keys => None
        return row.get(key)

    def _audit_request(response_body, http_status, run_id=None, idempotency_key=None, request_body=None):
        # Always record this endpoint invocation into api_requests.json
        db_obj = _load("api_requests.json")
        rows, mode = _ensure_api_requests_list(db_obj)

        now = _now_iso()
        req_id = _ulid_like("mas_req_")
        duration_ms = int((time.time() - t0) * 1000)
        if duration_ms < 0:
            duration_ms = 0

        if request_body is None:
            request_body = {
                "action": action,
                "api_request_id": api_request_id,
                "page": page,
                "page_size": page_size,
                "sort": sort,
                "filters": filters
            }

        row = {
            "id": req_id,
            "tool": "sequentialthinking",
            "run_id": run_id,
            "idempotency_key": idempotency_key,
            "caller": {},  # ambient auth layer not modeled; keep empty object
            "request_headers": {},
            "request_body": request_body if isinstance(request_body, dict) else {},
            "response_body": response_body,
            "http_status": http_status,
            "duration_ms": duration_ms,
            "created_at": now,
            "updated_at": now
        }

        rows.append(row)
        _save_api_requests(db_obj, mode, rows)
        return row

    # ---- validate inputs (do not over-validate beyond real rules) ----
    if action not in ("get_api_request", "list_api_requests"):
        resp = _err("VALIDATION_ERROR", "action must be one of: get_api_request, list_api_requests")
        _audit_request(resp, 400)
        return resp

    if action == "get_api_request":
        if api_request_id is None or not isinstance(api_request_id, str) or not api_request_id.strip():
            resp = _err("VALIDATION_ERROR", "api_request_id is required for action=get_api_request")
            _audit_request(resp, 400)
            return resp
        # IMPORTANT: do not reject non-matching ids with a regex validation here.
        # Real services typically accept any id string and return NOT_FOUND if absent.

    if action == "list_api_requests":
        if api_request_id is not None:
            resp = _err("VALIDATION_ERROR", "api_request_id is not allowed for action=list_api_requests")
            _audit_request(resp, 400)
            return resp

    if page is None:
        page = 1
    if page_size is None:
        page_size = 50

    page_i = _coerce_int(page, "page")
    page_size_i = _coerce_int(page_size, "page_size")
    if page_i is None or page_i < 1:
        resp = _err("VALIDATION_ERROR", "page must be an integer >= 1")
        _audit_request(resp, 400)
        return resp
    if page_size_i is None or page_size_i < 1 or page_size_i > 200:
        resp = _err("VALIDATION_ERROR", "page_size must be an integer between 1 and 200")
        _audit_request(resp, 400)
        return resp

    if sort is not None and not isinstance(sort, str):
        resp = _err("VALIDATION_ERROR", "sort must be a string")
        _audit_request(resp, 400)
        return resp

    if filters is not None and not isinstance(filters, dict):
        resp = _err("VALIDATION_ERROR", "filters must be an object")
        _audit_request(resp, 400)
        return resp

    # additionalProperties=false: only allow known filter keys
    allowed_filter_keys = {
        "tool", "run_id", "idempotency_key", "caller",
        "http_status_min", "http_status_max",
        "created_after", "created_before"
    }
    if isinstance(filters, dict):
        for k in filters.keys():
            if k not in allowed_filter_keys:
                resp = _err("VALIDATION_ERROR", f"filters contains unknown field '{k}' (additionalProperties=false)")
                _audit_request(resp, 400)
                return resp

        if "tool" in filters and filters["tool"] is not None and not isinstance(filters["tool"], str):
            resp = _err("VALIDATION_ERROR", "filters.tool must be a string")
            _audit_request(resp, 400)
            return resp
        if "run_id" in filters and filters["run_id"] is not None:
            if not isinstance(filters["run_id"], str):
                resp = _err("VALIDATION_ERROR", "filters.run_id must be a string")
                _audit_request(resp, 400)
                return resp
            # pattern declared; treat mismatch as validation error because it is an explicit business/schema rule
            if not re.match(r"^mas_run_[0-9A-HJKMNP-TV-Z]{10,}$", filters["run_id"]):
                resp = _err("VALIDATION_ERROR", "filters.run_id violates pattern '^mas_run_[0-9A-HJKMNP-TV-Z]{10,}$'")
                _audit_request(resp, 400)
                return resp

        if "idempotency_key" in filters and filters["idempotency_key"] is not None:
            v = filters["idempotency_key"]
            if not isinstance(v, str):
                resp = _err("VALIDATION_ERROR", "filters.idempotency_key must be a string")
                _audit_request(resp, 400)
                return resp
            if len(v) < 1 or len(v) > 256:
                resp = _err("VALIDATION_ERROR", "filters.idempotency_key length must be between 1 and 256")
                _audit_request(resp, 400)
                return resp

        if "caller" in filters and filters["caller"] is not None and not isinstance(filters["caller"], str):
            resp = _err("VALIDATION_ERROR", "filters.caller must be a string")
            _audit_request(resp, 400)
            return resp

        for k in ("http_status_min", "http_status_max"):
            if k in filters and filters[k] is not None:
                if isinstance(filters[k], bool) or not isinstance(filters[k], int):
                    resp = _err("VALIDATION_ERROR", f"filters.{k} must be an integer")
                    _audit_request(resp, 400)
                    return resp
                if filters[k] < 100 or filters[k] > 599:
                    resp = _err("VALIDATION_ERROR", f"filters.{k} must be between 100 and 599")
                    _audit_request(resp, 400)
                    return resp

        if "http_status_min" in filters and "http_status_max" in filters:
            a = filters.get("http_status_min")
            b = filters.get("http_status_max")
            if a is not None and b is not None and a > b:
                resp = _err("VALIDATION_ERROR", "filters.http_status_min must be <= filters.http_status_max")
                _audit_request(resp, 400)
                return resp

        for k in ("created_after", "created_before"):
            if k in filters and filters[k] is not None:
                if not isinstance(filters[k], str):
                    resp = _err("VALIDATION_ERROR", f"filters.{k} must be an RFC3339 date-time string")
                    _audit_request(resp, 400)
                    return resp
                if _parse_dt(filters[k]) is None:
                    resp = _err("VALIDATION_ERROR", f"filters.{k} must be a valid ISO-8601 date-time")
                    _audit_request(resp, 400)
                    return resp

    # ---- AUTHZ ----
    # No auth model present in datastore; do not fabricate forbidden.
    # This endpoint is accessible to the authenticated caller in this offline model.

    # ---- read from store ----
    db_obj = _load("api_requests.json")
    rows, mode = _ensure_api_requests_list(db_obj)

    if action == "get_api_request":
        found = None
        for r in rows:
            if isinstance(r, dict) and r.get("id") == api_request_id:
                found = r
                break
        if found is None:
            resp = _err("NOT_FOUND", "api_request not found", api_request_id=api_request_id)
            _audit_request(resp, 404)
            return resp

        resp = {"data": found}
        _audit_request(resp, 200, run_id=found.get("run_id"), idempotency_key=found.get("idempotency_key"))
        return resp

    # list_api_requests
    f = filters or {}
    tool_f = f.get("tool")
    run_id_f = f.get("run_id")
    idem_f = f.get("idempotency_key")
    caller_f = f.get("caller")
    hs_min = f.get("http_status_min")
    hs_max = f.get("http_status_max")
    created_after = _parse_dt(f.get("created_after")) if f.get("created_after") is not None else None
    created_before = _parse_dt(f.get("created_before")) if f.get("created_before") is not None else None

    out = []
    for r in rows:
        if not isinstance(r, dict):
            continue
        if tool_f is not None and r.get("tool") != tool_f:
            continue
        if run_id_f is not None and r.get("run_id") != run_id_f:
            continue
        if idem_f is not None and r.get("idempotency_key") != idem_f:
            continue
        if caller_f is not None:
            # caller is stored as object; allow matching against a stringified identifier if present.
            c = r.get("caller")
            if isinstance(c, dict):
                # try common fields; otherwise fallback to JSON string contains
                cid = c.get("id") or c.get("caller") or c.get("workspace") or c.get("tenant") or c.get("user")
                if cid != caller_f:
                    try:
                        if caller_f not in json.dumps(c, ensure_ascii=False, sort_keys=True):
                            continue
                    except Exception:
                        continue
            else:
                if str(c) != caller_f:
                    continue
        hs = r.get("http_status")
        if hs_min is not None:
            if not isinstance(hs, int) or hs < hs_min:
                continue
        if hs_max is not None:
            if not isinstance(hs, int) or hs > hs_max:
                continue

        ca = _parse_dt(r.get("created_at")) if r.get("created_at") is not None else None
        if created_after is not None:
            if ca is None or ca < created_after:
                continue
        if created_before is not None:
            if ca is None or ca >= created_before:
                continue

        out.append(r)

    # sorting
    sort_key = (sort or "-created_at").strip()
    desc = False
    if sort_key.startswith("-"):
        desc = True
        sort_key = sort_key[1:].strip()
    if not sort_key:
        sort_key = "created_at"

    # stable sort: unknown keys sort last
    def _sort_val(r):
        v = _get_sort_key(r, sort_key)
        if v is None:
            return (1, "")
        if isinstance(v, (int, float)):
            return (0, v)
        return (0, str(v))

    out.sort(key=_sort_val, reverse=desc)

    total = len(out)
    start = (page_i - 1) * page_size_i
    end = start + page_size_i
    page_rows = out[start:end]
    has_more = end < total

    next_cursor = None
    if has_more and page_rows:
        # cursor as "page:N" (simple, consistent)
        next_cursor = f"page:{page_i + 1}"

    resp = {
        "data": page_rows,
        "meta": {
            "page": page_i,
            "page_size": page_size_i,
            "total": total,
            "has_more": has_more,
            "next_cursor": next_cursor,
            "sort": (sort or "-created_at"),
            "filters": f
        }
    }
    _audit_request(resp, 200)
    return resp

def sequentialthinking_bulk(run_id, mode=None, steps=None, tool_calls=None, finalize_run=None, final_output=None, **_extra):
    import json, os, datetime, time, re, random

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0228000" if __import__("os").path.isdir("./environment_mix/0228000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now_dt = datetime.datetime.utcnow().replace(microsecond=0)
    now = now_dt.isoformat() + "Z"

    # Defaults
    if mode is None:
        mode = "upsert"
    if steps is None:
        steps = []
    if tool_calls is None:
        tool_calls = []
    if finalize_run is None:
        finalize_run = False

    # Validate inputs
    if not isinstance(run_id, str) or not re.match(r"^mas_run_[0-9A-HJKMNP-TV-Z]{10,}$", run_id):
        return _err("VALIDATION_ERROR", "run_id does not match required pattern")
    if mode not in ("create_only", "upsert"):
        return _err("VALIDATION_ERROR", "mode must be one of: create_only, upsert")
    if not isinstance(steps, list):
        return _err("VALIDATION_ERROR", "steps must be an array")
    if not isinstance(tool_calls, list):
        return _err("VALIDATION_ERROR", "tool_calls must be an array")
    if not isinstance(finalize_run, bool):
        return _err("VALIDATION_ERROR", "finalize_run must be a boolean")
    if final_output is not None and (not isinstance(final_output, str)):
        return _err("VALIDATION_ERROR", "final_output must be a string")
    if final_output is not None and len(final_output) > 200000:
        return _err("VALIDATION_ERROR", "final_output exceeds maximum length (200000)")

    # ID generator
    _CROCK = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
    def _gen(prefix):
        ts = int(time.time() * 1000)
        out = []
        for _ in range(10):
            out.append(_CROCK[ts % 32])
            ts //= 32
        for _ in range(16):
            out.append(_CROCK[random.randint(0, 31)])
        return prefix + "".join(out)

    def _parse_dt(s, field):
        if s is None:
            return None
        if not isinstance(s, str):
            raise ValueError(f"{field} must be a date-time string")
        try:
            ss = s[:-1] if s.endswith("Z") else s
            return datetime.datetime.fromisoformat(ss).replace(microsecond=0).isoformat() + "Z"
        except Exception:
            raise ValueError(f"{field} must be RFC3339/ISO-8601 date-time")

    # Load store
    api_requests = _load("api_requests.json")
    runs = _load("runs.json")
    steps_store = _load("steps.json")
    tool_calls_store = _load("tool_calls.json")
    agents = _load("agents.json")

    # Prepare and append api_requests audit row at end (but MUST be persisted; we persist now and update later)
    req_row = {
        "id": _gen("mas_req_"),
        "tool": "sequentialthinking",
        "run_id": run_id,
        "idempotency_key": None,
        "caller": {},
        "request_headers": {},
        "request_body": {
            "run_id": run_id,
            "mode": mode,
            "steps": steps,
            "tool_calls": tool_calls,
            "finalize_run": finalize_run,
            "final_output": final_output
        },
        "response_body": None,
        "http_status": None,
        "duration_ms": None,
        "created_at": now,
        "updated_at": now
    }
    api_requests.append(req_row)
    _save("api_requests.json", api_requests)

    def _finish(resp, http_status):
        dur = int((time.time() - t0) * 1000)
        req_row["response_body"] = resp
        req_row["http_status"] = int(http_status)
        req_row["duration_ms"] = dur if dur >= 0 else 0
        req_row["updated_at"] = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
        _save("api_requests.json", api_requests)
        return resp

    # Find run
    run = None
    run_i = None
    for i, r in enumerate(runs):
        if isinstance(r, dict) and r.get("id") == run_id:
            run = r
            run_i = i
            break
    if run is None:
        return _finish(_err("NOT_FOUND", "run not found", run_id=run_id), 404)

    # Index existing rows
    steps_by_id = {r.get("id"): r for r in steps_store if isinstance(r, dict) and r.get("id")}
    tools_by_id = {r.get("id"): r for r in tool_calls_store if isinstance(r, dict) and r.get("id")}

    # Uniqueness maps for constraints
    step_key_map = {}
    for r in steps_store:
        if not isinstance(r, dict):
            continue
        rid = r.get("run_id")
        si = r.get("step_index")
        if isinstance(rid, str) and isinstance(si, int):
            step_key_map[(rid, si)] = r.get("id")

    tool_key_map = {}
    for r in tool_calls_store:
        if not isinstance(r, dict):
            continue
        sid = r.get("step_id")
        qi = r.get("sequence_index")
        if isinstance(sid, str) and isinstance(qi, int):
            tool_key_map[(sid, qi)] = r.get("id")

    agents_by_id = {a.get("id"): a for a in agents if isinstance(a, dict) and a.get("id")}

    # Allowed transitions
    step_transitions = {
        "queued": {"running", "skipped", "cancelled"},
        "running": {"completed", "failed", "cancelled"},
        "completed": set(),
        "failed": set(),
        "skipped": set(),
        "cancelled": set()
    }
    tool_transitions = {
        "queued": {"running", "cancelled"},
        "running": {"succeeded", "failed", "cancelled"},
        "succeeded": set(),
        "failed": set(),
        "cancelled": set()
    }
    valid_step_status = set(step_transitions.keys())
    valid_tool_status = set(tool_transitions.keys())

    # Validate and stage mutations (do not partially write on errors)
    staged_steps_updates = []   # tuples: ("create"/"update", row_dict, index_in_store_or_None)
    staged_tool_updates = []

    # Pre-validate steps payload
    seen_step_payload_keys = set()
    for s in steps:
        if not isinstance(s, dict):
            return _finish(_err("VALIDATION_ERROR", "each step must be an object"), 400)
        if "step_index" not in s:
            return _finish(_err("VALIDATION_ERROR", "each step must include step_index"), 400)
        si = s.get("step_index")
        if not isinstance(si, int) or si < 0:
            return _finish(_err("VALIDATION_ERROR", "step_index must be an integer >= 0"), 400)
        seen_step_payload_keys.add(si)

        sid = s.get("id")
        if sid is not None:
            if not isinstance(sid, str) or not re.match(r"^mas_stp_[0-9A-HJKMNP-TV-Z]{10,}$", sid):
                return _finish(_err("VALIDATION_ERROR", "step.id does not match required pattern"), 400)

        st = s.get("status")
        if st is not None and st not in valid_step_status:
            return _finish(_err("VALIDATION_ERROR", "step.status is invalid"), 400)

        agent_id = s.get("agent_id")
        if agent_id is not None:
            if not isinstance(agent_id, str) or not re.match(r"^mas_agt_[0-9A-HJKMNP-TV-Z]{10,}$", agent_id):
                return _finish(_err("VALIDATION_ERROR", "step.agent_id does not match required pattern"), 400)
            a = agents_by_id.get(agent_id)
            if a is None:
                return _finish(_err("NOT_FOUND", "agent not found", agent_id=agent_id), 404)
            # Disabled agents cannot be newly assigned at assignment time
            if a.get("enabled") is not True:
                return _finish(_err("VALIDATION_ERROR", "cannot assign disabled agent to step", agent_id=agent_id), 400)

        for txt_field, maxlen in (("thought", 200000), ("result", 200000)):
            if s.get(txt_field) is not None:
                if not isinstance(s.get(txt_field), str):
                    return _finish(_err("VALIDATION_ERROR", f"step.{txt_field} must be a string"), 400)
                if len(s.get(txt_field)) > maxlen:
                    return _finish(_err("VALIDATION_ERROR", f"step.{txt_field} exceeds maximum length ({maxlen})"), 400)

        for tf in ("instruction", "error_message"):
            if s.get(tf) is not None and not isinstance(s.get(tf), str):
                return _finish(_err("VALIDATION_ERROR", f"step.{tf} must be a string"), 400)

        try:
            _ = _parse_dt(s.get("started_at"), "step.started_at")
            _ = _parse_dt(s.get("completed_at"), "step.completed_at")
        except ValueError as e:
            return _finish(_err("VALIDATION_ERROR", str(e)), 400)

    # Stage step mutations with uniqueness and transition checks
    for s in steps:
        si = s["step_index"]
        sid = s.get("id")

        existing = steps_by_id.get(sid) if sid else None
        is_create = existing is None

        if mode == "create_only" and not is_create:
            return _finish(_err("CONFLICT", "step exists but mode is create_only", step_id=sid), 409)

        # If upsert without id, we still must respect unique(run_id, step_index)
        existing_id_for_key = step_key_map.get((run_id, si))
        if is_create:
            if existing_id_for_key is not None:
                return _finish(_err("CONFLICT", "unique constraint violated for (run_id, step_index)", run_id=run_id, step_index=si), 409)
        else:
            # if updating, allow same row; but conflict if some other row holds this key
            if existing_id_for_key is not None and existing_id_for_key != existing.get("id"):
                return _finish(_err("CONFLICT", "unique constraint violated for (run_id, step_index)", run_id=run_id, step_index=si), 409)
            # ensure belongs to run
            if existing.get("run_id") != run_id:
                return _finish(_err("CONFLICT", "step belongs to a different run", step_id=existing.get("id")), 409)

        # Build new row state
        if is_create:
            new_id = sid if sid else _gen("mas_stp_")
            new_row = {
                "id": new_id,
                "run_id": run_id,
                "step_index": si,
                "status": s.get("status") or "queued",
                "agent_id": s.get("agent_id") if "agent_id" in s else None,
                "instruction": s.get("instruction") if "instruction" in s else None,
                "thought": s.get("thought") if "thought" in s else None,
                "result": s.get("result") if "result" in s else None,
                "error_message": s.get("error_message") if "error_message" in s else None,
                "started_at": _parse_dt(s.get("started_at"), "step.started_at") if "started_at" in s else None,
                "completed_at": _parse_dt(s.get("completed_at"), "step.completed_at") if "completed_at" in s else None,
                "created_at": now,
                "updated_at": now
            }
            # Enforce transition prerequisites: queued->running requires run running (also for create with status running)
            if new_row["status"] == "running" and run.get("status") != "running":
                return _finish(_err("INVALID_TRANSITION", "step cannot be running unless parent run is running", run_status=run.get("status")), 409)
            # Enforce completed_at presence for terminal states except skipped allowed but still must have completed_at if provided by rule
            if new_row["status"] in ("completed", "failed", "cancelled", "skipped"):
                if not new_row.get("completed_at"):
                    # schema note: skipped requires completed_at in store data patterns; enforce to satisfy constraints
                    new_row["completed_at"] = now
            if new_row["status"] == "running" and not new_row.get("started_at"):
                new_row["started_at"] = now
            staged_steps_updates.append(("create", new_row, None))
        else:
            # Transition validation if status provided
            new_row = dict(existing)
            old_status = existing.get("status")
            if "step_index" in s:
                new_row["step_index"] = si
            if "agent_id" in s:
                new_row["agent_id"] = s.get("agent_id")
            for f in ("instruction", "thought", "result", "error_message"):
                if f in s:
                    new_row[f] = s.get(f)
            if "started_at" in s:
                new_row["started_at"] = _parse_dt(s.get("started_at"), "step.started_at")
            if "completed_at" in s:
                new_row["completed_at"] = _parse_dt(s.get("completed_at"), "step.completed_at")

            if "status" in s and s.get("status") is not None:
                new_status = s["status"]
                if new_status != old_status:
                    allowed = step_transitions.get(old_status, set())
                    if new_status not in allowed:
                        return _finish(_err("INVALID_TRANSITION", "invalid step status transition", from_status=old_status, to_status=new_status), 409)
                    if new_status == "running" and run.get("status") != "running":
                        return _finish(_err("INVALID_TRANSITION", "step cannot transition to running unless parent run is running", run_status=run.get("status")), 409)
                    new_row["status"] = new_status
                    if new_status == "running" and not new_row.get("started_at"):
                        new_row["started_at"] = now
                    if new_status in ("completed", "failed", "cancelled", "skipped") and not new_row.get("completed_at"):
                        new_row["completed_at"] = now

            new_row["updated_at"] = now
            # Find index in store
            idx = None
            for i, r in enumerate(steps_store):
                if isinstance(r, dict) and r.get("id") == existing.get("id"):
                    idx = i
                    break
            if idx is None:
                return _finish(_err("NOT_FOUND", "step not found for update", step_id=existing.get("id")), 404)
            staged_steps_updates.append(("update", new_row, idx))

    # Validate and stage tool_calls
    for tc in tool_calls:
        if not isinstance(tc, dict):
            return _finish(_err("VALIDATION_ERROR", "each tool_call must be an object"), 400)
        for reqf in ("step_id", "sequence_index", "tool_name"):
            if reqf not in tc:
                return _finish(_err("VALIDATION_ERROR", f"tool_call missing required field {reqf}"), 400)

        t_id = tc.get("id")
        if t_id is not None:
            if not isinstance(t_id, str) or not re.match(r"^mas_tcl_[0-9A-HJKMNP-TV-Z]{10,}$", t_id):
                return _finish(_err("VALIDATION_ERROR", "tool_call.id does not match required pattern"), 400)

        step_id = tc.get("step_id")
        if not isinstance(step_id, str) or not re.match(r"^mas_stp_[0-9A-HJKMNP-TV-Z]{10,}$", step_id):
            return _finish(_err("VALIDATION_ERROR", "tool_call.step_id does not match required pattern"), 400)

        seq = tc.get("sequence_index")
        if not isinstance(seq, int) or seq < 0:
            return _finish(_err("VALIDATION_ERROR", "tool_call.sequence_index must be an integer >= 0"), 400)

        tool_name = tc.get("tool_name")
        if not isinstance(tool_name, str) or not tool_name.strip():
            return _finish(_err("VALIDATION_ERROR", "tool_call.tool_name must be a non-empty string"), 400)

        st = tc.get("status")
        if st is not None and st not in valid_tool_status:
            return _finish(_err("VALIDATION_ERROR", "tool_call.status is invalid"), 400)

        if "input" in tc and tc.get("input") is not None and not isinstance(tc.get("input"), dict):
            return _finish(_err("VALIDATION_ERROR", "tool_call.input must be an object"), 400)
        if "output" in tc and tc.get("output") is not None and not isinstance(tc.get("output"), dict):
            return _finish(_err("VALIDATION_ERROR", "tool_call.output must be an object"), 400)
        if "error_message" in tc and tc.get("error_message") is not None and not isinstance(tc.get("error_message"), str):
            return _finish(_err("VALIDATION_ERROR", "tool_call.error_message must be a string"), 400)

        if "duration_ms" in tc and tc.get("duration_ms") is not None:
            dm = tc.get("duration_ms")
            if not isinstance(dm, int) or dm < 0:
                return _finish(_err("VALIDATION_ERROR", "tool_call.duration_ms must be a non-negative integer"), 400)

        # Ensure step exists (either already or being created in this batch)
        step_exists = False
        for r in steps_store:
            if isinstance(r, dict) and r.get("id") == step_id and r.get("run_id") == run_id:
                step_exists = True
                break
        if not step_exists:
            for kind, srow, _idx in staged_steps_updates:
                if srow.get("id") == step_id and srow.get("run_id") == run_id:
                    step_exists = True
                    break
        if not step_exists:
            return _finish(_err("NOT_FOUND", "parent step not found for tool_call", step_id=step_id), 404)

    # Stage tool_call mutations with uniqueness and transitions
    for tc in tool_calls:
        t_id = tc.get("id")
        existing = tools_by_id.get(t_id) if t_id else None
        is_create = existing is None

        if mode == "create_only" and not is_create:
            return _finish(_err("CONFLICT", "tool_call exists but mode is create_only", tool_call_id=t_id), 409)

        step_id = tc["step_id"]
        seq = tc["sequence_index"]
        existing_id_for_key = tool_key_map.get((step_id, seq))

        if is_create:
            if existing_id_for_key is not None:
                return _finish(_err("CONFLICT", "unique constraint violated for (step_id, sequence_index)", step_id=step_id, sequence_index=seq), 409)
            new_id = t_id if t_id else _gen("mas_tcl_")
            new_row = {
                "id": new_id,
                "run_id": run_id,
                "step_id": step_id,
                "sequence_index": seq,
                "tool_name": tc["tool_name"],
                "status": tc.get("status") or "queued",
                "input": tc.get("input") if isinstance(tc.get("input"), dict) else {},
                "output": tc.get("output") if "output" in tc else None,
                "error_message": tc.get("error_message") if "error_message" in tc else None,
                "duration_ms": tc.get("duration_ms") if "duration_ms" in tc else None,
                "created_at": now,
                "updated_at": now
            }
            staged_tool_updates.append(("create", new_row, None))
        else:
            # conflict if other row holds key
            if existing_id_for_key is not None and existing_id_for_key != existing.get("id"):
                return _finish(_err("CONFLICT", "unique constraint violated for (step_id, sequence_index)", step_id=step_id, sequence_index=seq), 409)
            # Ensure belongs to the same step_id unless caller is effectively moving it (not supported)
            if existing.get("step_id") != step_id:
                return _finish(_err("CONFLICT", "cannot change tool_call.step_id for existing tool_call", tool_call_id=existing.get("id")), 409)

            new_row = dict(existing)
            old_status = existing.get("status")
            if "tool_name" in tc:
                new_row["tool_name"] = tc["tool_name"]
            if "input" in tc and tc.get("input") is not None:
                new_row["input"] = tc.get("input")
            if "output" in tc:
                new_row["output"] = tc.get("output")
            if "error_message" in tc:
                new_row["error_message"] = tc.get("error_message")
            if "duration_ms" in tc:
                new_row["duration_ms"] = tc.get("duration_ms")

            if "status" in tc and tc.get("status") is not None:
                new_status = tc["status"]
                if new_status != old_status:
                    allowed = tool_transitions.get(old_status, set())
                    if new_status not in allowed:
                        return _finish(_err("INVALID_TRANSITION", "invalid tool_call status transition", from_status=old_status, to_status=new_status), 409)
                    new_row["status"] = new_status

            new_row["updated_at"] = now
            idx = None
            for i, r in enumerate(tool_calls_store):
                if isinstance(r, dict) and r.get("id") == existing.get("id"):
                    idx = i
                    break
            if idx is None:
                return _finish(_err("NOT_FOUND", "tool_call not found for update", tool_call_id=existing.get("id")), 404)
            staged_tool_updates.append(("update", new_row, idx))

    # Apply staged writes
    created_steps = 0
    updated_steps = 0
    for kind, row, idx in staged_steps_updates:
        if kind == "create":
            steps_store.append(row)
            created_steps += 1
        else:
            steps_store[idx] = row
            updated_steps += 1

    created_tool_calls = 0
    updated_tool_calls = 0
    for kind, row, idx in staged_tool_updates:
        if kind == "create":
            tool_calls_store.append(row)
            created_tool_calls += 1
        else:
            tool_calls_store[idx] = row
            updated_tool_calls += 1

    # Persist step/tool_call changes
    _save("steps.json", steps_store)
    _save("tool_calls.json", tool_calls_store)

    # Optionally finalize run
    run_updated = False
    if finalize_run:
        # Run cannot transition to completed unless all non-skipped steps are completed
        # and steps must be contiguous step_index starting at 0 (no gaps) once completed.
        # Also only allow running->completed transition; enforce lifecycle.
        transitions = {
            "queued": {"running", "cancelled"},
            "running": {"completed", "failed", "cancelled"},
            "completed": set(),
            "failed": set(),
            "cancelled": set()
        }
        cur = run.get("status")
        if cur != "running":
            return _finish(_err("INVALID_TRANSITION", "run can only be finalized to completed from running", from_status=cur, to_status="completed"), 409)

        run_steps = [r for r in steps_store if isinstance(r, dict) and r.get("run_id") == run_id]
        non_skipped = [r for r in run_steps if r.get("status") != "skipped"]
        not_completed = [r for r in non_skipped if r.get("status") != "completed"]
        if not_completed:
            return _finish(
                _err(
                    "INVALID_TRANSITION",
                    "run cannot transition to completed unless all non-skipped steps are completed",
                    incomplete_step_ids=[r.get("id") for r in not_completed if r.get("id")]
                ),
                409
            )

        idxs = sorted([r.get("step_index") for r in run_steps if isinstance(r.get("step_index"), int)])
        if idxs:
            expected = list(range(0, len(idxs)))
            if idxs != expected:
                return _finish(
                    _err(
                        "INVALID_TRANSITION",
                        "run cannot be completed unless steps have contiguous step_index starting at 0",
                        step_indexes=idxs
                    ),
                    409
                )
        else:
            # If completing with no steps, that's allowed by schema? Business rule implies steps exist; enforce at least 0? We'll allow empty contiguous.
            pass

        # Apply completion
        run = dict(run)
        run["status"] = "completed"
        run["final_output"] = final_output if final_output is not None else run.get("final_output")
        if run.get("started_at") is None:
            run["started_at"] = now
        run["completed_at"] = now
        run["updated_at"] = now
        runs[run_i] = run
        _save("runs.json", runs)
        run_updated = True

    resp = {
        "run_id": run_id,
        "applied": {
            "steps_created": created_steps,
            "steps_updated": updated_steps,
            "tool_calls_created": created_tool_calls,
            "tool_calls_updated": updated_tool_calls,
            "run_completed": True if (finalize_run and run_updated) else False
        }
    }
    return _finish(resp, 200)
